mapper.select:
WITH grouped_loinc_data AS ( SELECT Distinct PFI, LOINC_1, LOINC_2, LOINC_3, LOINC_4, GROUP_COUNT GROUPED_LOINC FROM CODED_LOINC_GROUPING WHERE (end_date is null or end_Date > SYSDATE)
and PFI in (
#{pfi}
)
and (
(LOINC_1, LOINC_2, nvl(LOINC_3, 'X'), nvl(LOINC_4, 'X')) in
( select #{loincCode} from dual)
))
SELECT REFRENCE.RANKING, REFRENCE.DOCUMENT_ID, REFRENCE.OBXLOINCCODE, REFRENCE.MSHLABPFI, REFRENCE.MSHSENDINGFACILITYCLIA, REFRENCE.PIDLASTNAME, REFRENCE.PIDFIRSTNAME, REFRENCE.PIDMIDDLENAME, REFRENCE.PIDNAMESUFFIX, TO_CHAR(REFRENCE.PIDDATEOFBIRTH, 'MM/DD/YYYY') PIDDATEOFBIRTH, REFRENCE.PIDSSN, TO_CHAR(REFRENCE.PIDDEATHDATE, 'MM/DD/YYYY') PIDDEATHDATE, REFRENCE.PIDMEDICALRECORDNUMBER, REFRENCE.PIDPATIENTACCOUNTNUM, REFRENCE.PIDTYPEOFINSURANCE, REFRENCE.PIDNYSID, REFRENCE.PIDDIN, REFRENCE.PIDADDRESSLINE1, REFRENCE.PIDADDRESSLINE2, REFRENCE.PIDCITY, REFRENCE.PIDSTATE, REFRENCE.PIDZIPCODE, REFRENCE.PIDHOMEPHONE, REFRENCE.PIDSEXCODE, REFRENCE.PIDRACEASIAN, REFRENCE.PIDRACEBLACK, REFRENCE.PIDRACENATIVEAMERALASKAN, REFRENCE.PIDRACEOTHER, REFRENCE.PIDRACEPACIFIC, REFRENCE.PIDRACEUNKNOWN, REFRENCE.PIDRACEWHITE, REFRENCE.PIDETHNICGROUPCODE, REFRENCE.PIDFACILITYIDINTERNAL, REFRENCE.PIDFACILITYIDEXTERNAL, REFRENCE.PIDCOUNTRYOFORIGIN, REFRENCE.PIDLENGTHOFRESIDENCY, REFRENCE.OBRPROVIDERLASTNAME, REFRENCE.OBRPROVIDERFIRSTNAME, REFRENCE.OBRPROVIDERMIDDLENAME, TO_CHAR(REFRENCE.OBRCOLLECTIONDATE, 'MM/DD/YYYY') OBRCOLLECTIONDATE, REFRENCE.OBRACCESSIONNUM, REFRENCE.ZLRPROVIDERADDRESSLINE1, REFRENCE.ZLRPROVIDERADDRESSLINE2, REFRENCE.ZLRPROVIDERCITY, REFRENCE.ZLRPROVIDERSTATE, REFRENCE.ZLRPROVIDERZIPCODE, REFRENCE.OBRCALLBACKPHONE, REFRENCE.ZLRFACILITYNAME, REFRENCE.ZLRFACILITYADDRESSLINE1, REFRENCE.ZLRFACILITYADDRESSLINE2, REFRENCE.ZLRFACILITYCITY, REFRENCE.ZLRFACILITYSTATE, REFRENCE.ZLRFACILITYZIPCODE, REFRENCE.ZLRFACILITYPHONE, REFRENCE.ZLRNEXTOFKINRELATIONSHIP, REFRENCE.ZLRNEXTOFKINLASTNAME, REFRENCE.ZLRNEXTOFKINFIRSTNAME, REFRENCE.ZLRNEXTOFKINMIDDLENAME, REFRENCE.ZLRNEXTOFKINADDRESSLINE1, REFRENCE.ZLRNEXTOFKINADDRESSLINE2, REFRENCE.ZLRNEXTOFKINCITY, REFRENCE.ZLRNEXTOFKINSTATE, REFRENCE.ZLRNEXTOFKINZIPCODE, REFRENCE.ZLRNEXTOFKINPHONE FROM (SELECT MAX (DOCUMENT_ID) OVER (PARTITION BY MSHSENDINGFACILITYCLIA, PIDLASTNAME, PIDFIRSTNAME, PIDMIDDLENAME, PIDNAMESUFFIX, PIDDATEOFBIRTH, PIDSSN, PIDDEATHDATE, PIDMEDICALRECORDNUMBER, PIDPATIENTACCOUNTNUM, PIDTYPEOFINSURANCE, PIDNYSID, PIDDIN, PIDADDRESSLINE1, PIDADDRESSLINE2, PIDCITY, PIDSTATE, PIDZIPCODE, PIDHOMEPHONE, PIDSEXCODE, PIDRACEASIAN, PIDRACEBLACK, PIDRACENATIVEAMERALASKAN, PIDRACEOTHER, PIDRACEPACIFIC, PIDRACEUNKNOWN, PIDRACEWHITE, PIDETHNICGROUPCODE, PIDFACILITYIDINTERNAL, PIDFACILITYIDEXTERNAL, PIDCOUNTRYOFORIGIN, PIDLENGTHOFRESIDENCY, OBRPROVIDERLASTNAME, OBRPROVIDERFIRSTNAME, OBRPROVIDERMIDDLENAME, OBRCOLLECTIONDATE, OBRACCESSIONNUM, ZLRPROVIDERADDRESSLINE1, ZLRPROVIDERADDRESSLINE2, ZLRPROVIDERCITY, ZLRPROVIDERSTATE, ZLRPROVIDERZIPCODE, OBRCALLBACKPHONE, ZLRFACILITYNAME, ZLRFACILITYADDRESSLINE1, ZLRFACILITYADDRESSLINE2, ZLRFACILITYCITY, ZLRFACILITYSTATE, ZLRFACILITYZIPCODE, ZLRFACILITYPHONE, ZLRNEXTOFKINRELATIONSHIP, ZLRNEXTOFKINLASTNAME, ZLRNEXTOFKINFIRSTNAME, ZLRNEXTOFKINMIDDLENAME, ZLRNEXTOFKINADDRESSLINE1, ZLRNEXTOFKINADDRESSLINE2, ZLRNEXTOFKINCITY, ZLRNEXTOFKINSTATE, ZLRNEXTOFKINZIPCODE, ZLRNEXTOFKINPHONE ORDER BY MSHSENDINGFACILITYCLIA, PIDLASTNAME, PIDFIRSTNAME, PIDMIDDLENAME, PIDNAMESUFFIX, PIDDATEOFBIRTH, PIDSSN, PIDDEATHDATE, PIDMEDICALRECORDNUMBER, PIDPATIENTACCOUNTNUM, PIDTYPEOFINSURANCE, PIDNYSID, PIDDIN, PIDADDRESSLINE1, PIDADDRESSLINE2, PIDCITY, PIDSTATE, PIDZIPCODE, PIDHOMEPHONE, PIDSEXCODE, PIDRACEASIAN, PIDRACEBLACK, PIDRACENATIVEAMERALASKAN, PIDRACEOTHER, PIDRACEPACIFIC, PIDRACEUNKNOWN, PIDRACEWHITE, PIDETHNICGROUPCODE, PIDFACILITYIDINTERNAL, PIDFACILITYIDEXTERNAL, PIDCOUNTRYOFORIGIN, PIDLENGTHOFRESIDENCY, OBRPROVIDERLASTNAME, OBRPROVIDERFIRSTNAME, OBRPROVIDERMIDDLENAME, OBRCOLLECTIONDATE, OBRACCESSIONNUM, ZLRPROVIDERADDRESSLINE1, ZLRPROVIDERADDRESSLINE2, ZLRPROVIDERCITY, ZLRPROVIDERSTATE, ZLRPROVIDERZIPCODE, OBRCALLBACKPHONE, ZLRFACILITYNAME, ZLRFACILITYADDRESSLINE1, ZLRFACILITYADDRESSLINE2, ZLRFACILITYCITY, ZLRFACILITYSTATE, ZLRFACILITYZIPCODE, ZLRFACILITYPHONE, ZLRNEXTOFKINRELATIONSHIP, ZLRNEXTOFKINLASTNAME, ZLRNEXTOFKINFIRSTNAME, ZLRNEXTOFKINMIDDLENAME, ZLRNEXTOFKINADDRESSLINE1, ZLRNEXTOFKINADDRESSLINE2, ZLRNEXTOFKINCITY, ZLRNEXTOFKINSTATE, ZLRNEXTOFKINZIPCODE, ZLRNEXTOFKINPHONE) RANKING, R.* FROM RAW_HIV_ECLRS_DOC R, grouped_loinc_data l WHERE CURRENT_PROCESS_STATUS IN (11) AND r.MSHLABPFI = l.pfi AND Regexp_Like(l.loinc_1||l.loinc_2||l.loinc_3||l.loinc_4, r.OBXLOINCCODE) AND l.GROUPED_LOINC > 0
) REFRENCE ORDER BY REFRENCE.MSHSENDINGFACILITYCLIA, REFRENCE.PIDLASTNAME, REFRENCE.PIDFIRSTNAME, REFRENCE.PIDMIDDLENAME, REFRENCE.PIDNAMESUFFIX, REFRENCE.PIDDATEOFBIRTH, REFRENCE.PIDSSN, REFRENCE.PIDDEATHDATE, REFRENCE.PIDMEDICALRECORDNUMBER, REFRENCE.PIDPATIENTACCOUNTNUM, REFRENCE.PIDTYPEOFINSURANCE, REFRENCE.PIDNYSID, REFRENCE.PIDDIN, REFRENCE.PIDADDRESSLINE1, REFRENCE.PIDADDRESSLINE2, REFRENCE.PIDCITY, REFRENCE.PIDSTATE, REFRENCE.PIDZIPCODE, REFRENCE.PIDHOMEPHONE, REFRENCE.PIDSEXCODE, REFRENCE.PIDRACEASIAN, REFRENCE.PIDRACEBLACK, REFRENCE.PIDRACENATIVEAMERALASKAN, REFRENCE.PIDRACEOTHER, REFRENCE.PIDRACEPACIFIC, REFRENCE.PIDRACEUNKNOWN, REFRENCE.PIDRACEWHITE, REFRENCE.PIDETHNICGROUPCODE, REFRENCE.PIDFACILITYIDINTERNAL, REFRENCE.PIDFACILITYIDEXTERNAL, REFRENCE.PIDCOUNTRYOFORIGIN, REFRENCE.PIDLENGTHOFRESIDENCY, REFRENCE.OBRPROVIDERLASTNAME, REFRENCE.OBRPROVIDERFIRSTNAME, REFRENCE.OBRPROVIDERMIDDLENAME, REFRENCE.OBRCOLLECTIONDATE, REFRENCE.OBRACCESSIONNUM, REFRENCE.ZLRPROVIDERADDRESSLINE1, REFRENCE.ZLRPROVIDERADDRESSLINE2, REFRENCE.ZLRPROVIDERCITY, REFRENCE.ZLRPROVIDERSTATE, REFRENCE.ZLRPROVIDERZIPCODE, REFRENCE.OBRCALLBACKPHONE, REFRENCE.ZLRFACILITYNAME, REFRENCE.ZLRFACILITYADDRESSLINE1, REFRENCE.ZLRFACILITYADDRESSLINE2, REFRENCE.ZLRFACILITYCITY, REFRENCE.ZLRFACILITYSTATE, REFRENCE.ZLRFACILITYZIPCODE, REFRENCE.ZLRFACILITYPHONE, REFRENCE.ZLRNEXTOFKINRELATIONSHIP, REFRENCE.ZLRNEXTOFKINLASTNAME, REFRENCE.ZLRNEXTOFKINFIRSTNAME, REFRENCE.ZLRNEXTOFKINMIDDLENAME, REFRENCE.ZLRNEXTOFKINADDRESSLINE1, REFRENCE.ZLRNEXTOFKINADDRESSLINE2, REFRENCE.ZLRNEXTOFKINCITY, REFRENCE.ZLRNEXTOFKINSTATE, REFRENCE.ZLRNEXTOFKINZIPCODE, REFRENCE.ZLRNEXTOFKINPHONE, REFRENCE.RANKING

select * from RAW_HIV_ECLRS_DOC where document_id in (

		#{documentId}

)
